export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
export type Damage = { itemType: string; amount: number };
export type QuoteStep = { op: "quote"; items: Item[] };
export type ClaimStep = { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
export type Scenario = { customer: { yearsWithMHPCO: number }; steps: (QuoteStep | ClaimStep)[] };
export type StepResult = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  return { results: scenario.steps.map(() => ({ premium: PROCESSING_FEE })) };
}
import { describe, expect, it } from "vitest";
import { runScenario } from "./claimOffice.js";

type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };

function premiumFor(items: Item[], yearsWithMHPCO = 0): number {
  const { results } = runScenario({ customer: { yearsWithMHPCO }, steps: [{ op: "quote", items }] });
  return (results[0] as { premium: number }).premium;
}

describe("quote", () => {
  it("empty item list -> premium 5 G (fee only; first insurance on 0 G base)", () => {
    expect(premiumFor([])).toBe(5);
  });
  it.todo("newcomer with a plain sword -> 100 base + 10 first insurance + 5 fee = 115 G");
  it.todo("newcomer with a plain amulet -> 60 + 6 + 5 = 71 G");
  it.todo("newcomer with a plain staff -> 80 + 8 + 5 = 93 G");
  it.todo("newcomer with a plain potion -> 40 + 4 + 5 = 49 G");
  it.todo("2 runes -> 50 G base -> 50 + 5 + 5 = 60 G");
  it.todo("3 runes -> block 60 G base -> 60 + 6 + 5 = 71 G");
  it.todo("4 runes -> no block, 100 G base -> 100 + 10 + 5 = 115 G");
  it.todo("7 runes -> no block, 175 G base -> 175 + 17.5 + 5 = 197.5 -> rounded up to 198 G");
  it.todo("2 moonstones -> 50 G base -> 60 G (moonstone is a component)");
  it.todo("2 runes + 1 moonstone -> 75 G base, no block across types -> 75 + 7.5 + 5 = 87.5 -> 88 G");
  it.todo("3 runes + 3 moonstones -> two blocks, 120 G base -> 120 + 12 + 5 = 137 G");
  it.todo("newcomer with a cursed sword (steel, enchantment 3) -> 165 G");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge -> 115 G");
  it.todo("sword with exactly enchantment 5 -> 30% surcharge -> 100 + 30 + 10 + 5 = 145 G");
  it.todo("cursed sword with enchantment 5 -> both surcharges -> 100 + 50 + 30 + 10 + 5 = 195 G");
  it.todo("cursed sword + plain amulet -> curse only on sword: 160 + 50 + 16 first insurance + 5 = 231 G");
  it.todo("high enchantment only on the enchanted item: enchantment-5 sword + plain amulet -> 160 + 30 + 16 + 5 = 211 G");
  it.todo("customer with exactly 2 years -> loyalty discount: plain sword -> 100 - 20 + 10 + 5 = 95 G");
  it.todo("customer with 1 year -> no loyalty discount: plain sword -> 115 G");
  it.todo("second quote in a scenario gets the 15% follow-up discount: plain sword twice -> 115 G then 100 G");
  it.todo("long-standing customer's second contract, cursed sword enchantment 7 -> 160 G");
  it.todo("throws Error for an unknown item type (broomstick)");
});

describe("claim", () => {
